// Verificar si estamos en horario bursátil (Lunes a Viernes de 08:30 a 16:30 hrs Santiago)
// Si es ejecución manual (Test Manual), siempre permitimos continuar.

const isManual = $input.first().json?.isManual ?? false;

// Obtenemos la hora en zona horaria America/Santiago
const now = new Date();
const santiagoTimeString = now.toLocaleString("en-US", { timeZone: "America/Santiago", hour12: false });
const santiagoDate = new Date(santiagoTimeString);

const dayOfWeek = santiagoDate.getDay(); // 0 = Domingo, 1 = Lunes, ..., 5 = Viernes, 6 = Sábado
const hours = santiagoDate.getHours();
const minutes = santiagoDate.getMinutes();
const currentTimeMinutes = hours * 60 + minutes;

const marketOpen = 8 * 60 + 30;  // 08:30 hrs
const marketClose = 16 * 60 + 30; // 16:30 hrs

const isWeekday = (dayOfWeek >= 1 && dayOfWeek <= 5);
const isMarketHours = (currentTimeMinutes >= marketOpen && currentTimeMinutes <= marketClose);

const allowExecution = isManual || (isWeekday && isMarketHours);

return [{
  json: {
    allowExecution,
    isManual,
    santiagoTime: santiagoTimeString,
    dayOfWeek,
    hours,
    minutes,
    isMarketHours
  }
}];

// ====================================================================
// Parser de Mercado Bolsa de Santiago e Indicadores Económicos
// ====================================================================

function parseChileanNumber(str) {
  if (!str) return null;
  const cleaned = str.replace(/[+%]/g, '').trim().replace(/\./g, '').replace(',', '.');
  const num = parseFloat(cleaned);
  return isNaN(num) ? null : num;
}

// Obtenemos los HTML de ambas peticiones
const items = $input.all();
let corredoraHtml = '';
let inversionesHtml = '';

for (const item of items) {
  const data = typeof item.json.data === 'string' ? item.json.data : JSON.stringify(item.json);
  if (data.includes('Acciones IPSA') || data.includes('indicesSectorialName')) {
    corredoraHtml = data;
  }
  if (data.includes('currencyName') || data.includes('commmoditiesName')) {
    inversionesHtml = data;
  }
}

const fechaCaptura = new Date().toISOString();

// --------------------------------------------------------------------
// 1. IPSA PRINCIPAL & RENTABILIDAD
// --------------------------------------------------------------------
let ipsaRecord = null;
if (corredoraHtml) {
  const ipsaPriceMatch = corredoraHtml.match(/class="valor"[^>]*>\s*<strong>([^<]+)<\/strong>/);
  const ipsaVarMatch = corredoraHtml.match(/Var\. % d[ií]a[\s\S]*?class="nemo[^"]*">\s*([^<\s]+)/);
  const ipsaDateMatch = corredoraHtml.match(/Fecha\s*<strong>([^<]+)<\/strong>/);
  const ipsaPointsMatch = corredoraHtml.match(/\[\s*<span[^>]*class="nemo[^"]*">\s*([^<]+)\s*<\/span>\s*\]/);

  const minValMatch = corredoraHtml.match(/Valor\s+m(?:[ií]|&iacute;)nimo\s+del\s+d(?:[ií]|&iacute;)a:[\s\S]*?<span class="valor">\s*([^<]+)\s*<\/span>/i);
  const maxValMatch = corredoraHtml.match(/Valor\s+m(?:[aá]|&aacute;)ximo\s+del\s+d(?:[ií]|&iacute;)a:[\s\S]*?<span class="valor">\s*([^<]+)\s*<\/span>/i);
  const rentMtdMatch = corredoraHtml.match(/Mes a la fecha:[\s\S]*?<span class="[^"]*">\s*([^<]+)\s*<\/span>/i);
  const rent1mMatch = corredoraHtml.match(/1 Mes:[\s\S]*?<span class="[^"]*">\s*([^<]+)\s*<\/span>/i);
  const rent3mMatch = corredoraHtml.match(/3 Meses:[\s\S]*?<span class="[^"]*">\s*([^<]+)\s*<\/span>/i);
  const rent6mMatch = corredoraHtml.match(/6 Meses:[\s\S]*?<span class="[^"]*">\s*([^<]+)\s*<\/span>/i);
  const rentYtdMatch = corredoraHtml.match(/(?:Año|A&ntilde;o)\s+a\s+la\s+Fecha:[\s\S]*?<span class="[^"]*">\s*([^<]+)\s*<\/span>/i);

  ipsaRecord = {
    fecha_captura: fechaCaptura,
    fecha_mercado: ipsaDateMatch ? ipsaDateMatch[1].trim() : null,
    precio: parseChileanNumber(ipsaPriceMatch ? ipsaPriceMatch[1] : null),
    variacion_pct: parseChileanNumber(ipsaVarMatch ? ipsaVarMatch[1] : null),
    variacion_puntos: parseChileanNumber(ipsaPointsMatch ? ipsaPointsMatch[1] : null),
    min_dia: parseChileanNumber(minValMatch ? minValMatch[1] : null),
    max_dia: parseChileanNumber(maxValMatch ? maxValMatch[1] : null),
    rent_mes_fecha: parseChileanNumber(rentMtdMatch ? rentMtdMatch[1] : null),
    rent_1m: parseChileanNumber(rent1mMatch ? rent1mMatch[1] : null),
    rent_3m: parseChileanNumber(rent3mMatch ? rent3mMatch[1] : null),
    rent_6m: parseChileanNumber(rent6mMatch ? rent6mMatch[1] : null),
    rent_ytd: parseChileanNumber(rentYtdMatch ? rentYtdMatch[1] : null)
  };
}

// --------------------------------------------------------------------
// 2. ACCIONES IPSA (30 Acciones)
// --------------------------------------------------------------------
const accionesList = [];
if (corredoraHtml) {
  const constituentsMap = {};
  const jsonConstituentsMatch = corredoraHtml.match(/var jsonConstituents = (\[.*?\]);/s);
  if (jsonConstituentsMatch) {
    try {
      const list = JSON.parse(jsonConstituentsMatch[1]);
      list.forEach(c => { constituentsMap[c.symbol] = c.name; });
    } catch (e) {}
  }

  const stockRowRegex = /<td class="con-nombre">\s*<span class="ins constituentsNotation"[^>]*title="([^"]+)"[^>]*>\s*([^<]+)\s*<\/span>\s*<\/td>\s*<td class="con-valor">\s*<span[^>]*>\s*([^<]+)\s*<\/span>\s*<\/td>\s*<td class="con-var">\s*<span[^>]*class="nemo\s+([^"]+)"[^>]*>\s*([^<]+)\s*<\/span>/g;
  let match;
  while ((match = stockRowRegex.exec(corredoraHtml)) !== null) {
    const symbol = match[1].trim();
    accionesList.push({
      fecha_captura: fechaCaptura,
      symbol: symbol,
      nombre: constituentsMap[symbol] || symbol,
      precio: parseChileanNumber(match[3]),
      variacion_pct: parseChileanNumber(match[5]),
      direccion: match[4].trim()
    });
  }
}

// --------------------------------------------------------------------
// 3. ÍNDICES SECTORIALES
// --------------------------------------------------------------------
const sectorialesList = [];
if (corredoraHtml) {
  const sectorRegex = /<span id="[0-9]+_([A-Z0-9]+)" class="ins indicesSectorialName">\s*([^<]+)\s*<\/span>\s*<\/td>\s*<td class="con-valor">\s*<span[^>]*>\s*([^<]+)\s*<\/span>\s*<\/td>\s*<td class="con-var">\s*<span class="nemo\s+([^"]+)"[^>]*>\s*([^<]+)\s*<\/span>/g;
  let match;
  while ((match = sectorRegex.exec(corredoraHtml)) !== null) {
    sectorialesList.push({
      fecha_captura: fechaCaptura,
      codigo: match[1].trim(),
      puntos: parseChileanNumber(match[3]),
      variacion_pct: parseChileanNumber(match[5]),
      direccion: match[4].trim()
    });
  }
}

// --------------------------------------------------------------------
// 4. MAYORES ALZAS Y BAJAS
// --------------------------------------------------------------------
const topsList = [];
if (corredoraHtml) {
  const topRegex = /<span class="ins stockTop" title=([^>]+) id="TOP_name_[0-9]+">\s*([^<]+)\s*<\/span>[\s\S]*?<span class="off" id="TOP_price_[0-9]+">\s*([^<]+)\s*<\/span>[\s\S]*?<span class="([^"]+)" id="TOP_pct_[0-9]+">\s*([^<]+)\s*<\/span>/g;
  let match;
  let pos = 1;
  while ((match = topRegex.exec(corredoraHtml)) !== null) {
    topsList.push({
      fecha_captura: fechaCaptura,
      tipo: 'alza',
      posicion: pos++,
      symbol: match[2].trim(),
      precio: parseChileanNumber(match[3]),
      variacion_pct: parseChileanNumber(match[5]),
      direccion: match[4].trim()
    });
  }

  const flopRegex = /<span class="ins stockFlop" title=([^>]+) id="FLOP_name_[0-9]+">\s*([^<]+)\s*<\/span>[\s\S]*?<span class="off" id="FLOP_price_[0-9]+">\s*([^<]+)\s*<\/span>[\s\S]*?<span class="([^"]+)" id="FLOP_pct_[0-9]+">\s*([^<]+)\s*<\/span>/g;
  pos = 1;
  while ((match = flopRegex.exec(corredoraHtml)) !== null) {
    topsList.push({
      fecha_captura: fechaCaptura,
      tipo: 'baja',
      posicion: pos++,
      symbol: match[2].trim(),
      precio: parseChileanNumber(match[3]),
      variacion_pct: parseChileanNumber(match[5]),
      direccion: match[4].trim()
    });
  }
}

// --------------------------------------------------------------------
// 5. INDICADORES ECONÓMICOS (UF, UTM, Dólar, etc.)
// --------------------------------------------------------------------
const indicadoresList = [];
if (inversionesHtml) {
  const indRegex = /<span id="[0-9]+_([^"]+)" class="ins currencyName">\s*([^<]+)\s*<\/span>\s*<\/td>\s*<td class="con-valor">\s*<span[^>]*>\s*([^<]+)\s*<\/span>\s*<\/td>\s*<td class="con-var">\s*<span class="([^"]+)"[^>]*>\s*([^<]+)\s*<\/span>/g;
  let match;
  while ((match = indRegex.exec(inversionesHtml)) !== null) {
    indicadoresList.push({
      fecha_captura: fechaCaptura,
      nombre: match[2].trim(),
      valor: parseChileanNumber(match[3]),
      variacion_pct: parseChileanNumber(match[5]),
      direccion: match[4].trim()
    });
  }
}

// --------------------------------------------------------------------
// 6. COMMODITIES (Cobre Cash, Futuro, Petróleo, etc.)
// --------------------------------------------------------------------
const commoditiesList = [];
if (inversionesHtml) {
  const commRegex = /<span id="[0-9]+_([^"]+)" class="ins commmoditiesName">\s*([^<]+)\s*<\/span>\s*<\/td>\s*<td class="con-valor">\s*<span[^>]*>\s*([^<]+)\s*<\/span>\s*<\/td>\s*<td class="con-var">\s*<span class="([^"]+)"[^>]*>\s*([^<]+)\s*<\/span>/g;
  let match;
  while ((match = commRegex.exec(inversionesHtml)) !== null) {
    commoditiesList.push({
      fecha_captura: fechaCaptura,
      nombre: match[2].trim(),
      valor: parseChileanNumber(match[3]),
      variacion_pct: parseChileanNumber(match[5]),
      direccion: match[4].trim()
    });
  }
}

// Retornamos un objeto consolidado para las ramas de inserción en PostgreSQL
return [{
  json: {
    fecha_captura: fechaCaptura,
    ipsa: ipsaRecord,
    acciones: accionesList,
    indicadores: indicadoresList,
    commodities: commoditiesList,
    sectoriales: sectorialesList,
    tops: topsList,
    resumen: {
      total_acciones: accionesList.length,
      total_indicadores: indicadoresList.length,
      total_commodities: commoditiesList.length,
      total_sectoriales: sectorialesList.length,
      total_tops: topsList.length
    }
  }
}];

// Extraer el array de acciones para inserción por lotes en PostgreSQL
const parent = $input.first().json;
return (parent.acciones || []).map(item => ({ json: item }));

// Extraer el array de indicadores económicos para inserción en PostgreSQL
const parent = $input.first().json;
return (parent.indicadores || []).map(item => ({ json: item }));

// Extraer commodities y sectores para inserción
const parent = $input.first().json;
const commodities = (parent.commodities || []).map(item => ({ json: { ...item, _type: 'commodity' } }));
const sectoriales = (parent.sectoriales || []).map(item => ({ json: { ...item, _type: 'sectorial' } }));
return [...commodities, ...sectoriales];
